  {
    "signature": "scoring_authority.enqueue_competition_derived_job(text,text,text,jsonb)",
    "old_hash": "70693461585f13dc1412089013a8d850a06346ed040ff820c6f337c940f4b613",
    "new_hash": "6c335364e067023d8a7d39e0d3415e06792c5debc82fd7e3ff3a99d614b646c1",
    "edits": [
      {
        "old": "\nbegin\n  insert into scoring_authority.competition_recalculation_jobs (\n    tournament_id, round_number, engine_key, status, requested_source_revision,\n    requested_at, updated_at\n  ) values (\n    target_tournament, 0, target_engine, 'PENDING',\n    jsonb_build_object('reason', reason_value, 'revision', coalesce(revision_value, '{}'::jsonb)),\n    now(), now()\n  ) on conflict (tournament_id, round_number, engine_key) do update set\n    status = 'PENDING', requested_source_revision = excluded.requested_source_revision,\n    requested_at = now(), started_at = null, completed_at = null,\n    last_error_code = null, last_error_safe = null, updated_at = now();\nend;\n",
        "new": "\nbegin\n  -- Legacy and canonical match triggers describe the same match revision.\n  -- Include the canonical scorecard fact omitted by the legacy trigger; request\n  -- reasons/provenance are not a new source or a new retry budget.\n  if reason_value in('MATCH_CHANGE','OFFICIAL_RESULT_CHANGE') then\n    revision_value:=revision_value||jsonb_build_object('scorecardComplete',(\n      select m.scorecard_complete from scoring_authority.matches m\n      where m.tournament_id=target_tournament and m.match_id=revision_value->>'matchId'\n        and m.match_revision=(revision_value->>'matchRevision')::bigint));\n  end if;\n  insert into scoring_authority.competition_recalculation_jobs (\n    tournament_id, round_number, engine_key, status, requested_source_revision,\n    requested_at, updated_at\n  ) values (\n    target_tournament, 0, target_engine, 'PENDING',\n    jsonb_build_object('reason', reason_value, 'revision', coalesce(revision_value, '{}'::jsonb)),\n    now(), now()\n  ) on conflict (tournament_id, round_number, engine_key) do update set\n    status = 'PENDING', requested_source_revision = excluded.requested_source_revision,\n    requested_at = now(), started_at = null, completed_at = null,\n    last_error_code = null, last_error_safe = null, updated_at = now();\nend;\n"
      }
    ]
  },
  {
    "signature": "scoring_authority.enqueue_annual_derived_v1_change()",
    "old_hash": "e229969e804bab6f244755f3f0cdad4085f1c4d025e1018f2df8dbb587889b86",
    "new_hash": "8e6360906cccae64029e93137afe3bea6ab0a8fd603a1f4c311a4ecc2c68afd4",
    "edits": [
      {
        "old": "\ndeclare\n  target_match text;\n  target_tournament text;\n  current_tournament text;\n  runtime_generation uuid;\n  reason_value text;\n  revision_value jsonb;\n  engine_values text[];\n  engine_value text;\nbegin\n  if tg_table_schema <> 'scoring_authority'\n     or tg_table_name not in (\n       'hole_scores', 'matches', 'odds_published_snapshots',\n       'net_skins_v1_result_revisions'\n     ) then\n    raise exception using errcode = '55000',\n      message = 'PRODUCTION_ANNUAL_DERIVED_TRIGGER_SCOPE_INVALID';\n  end if;\n  if tg_table_name = 'hole_scores' then\n    target_match := case when tg_op = 'DELETE'\n      then old.match_id else new.match_id end;\n    select value.tournament_id into target_tournament\n    from scoring_authority.matches value\n    where value.match_id = target_match;\n    reason_value := 'CANONICAL_HOLE_SCORE_CHANGED';\n    revision_value := pg_catalog.jsonb_build_object(\n      'matchId', target_match,\n      'holeNumber', case when tg_op = 'DELETE'\n        then old.hole_number else new.hole_number end,\n      'holeRevision', case when tg_op = 'DELETE'\n        then old.hole_revision else new.hole_revision end\n    );\n    engine_values := array[\n      'TEAM_MOMENTUM', 'TOURNAMENT_STORYLINES',\n      'TOURNAMENT_INTELLIGENCE', 'PROJECTION_EDITORIAL',\n      'TOURNAMENT_FINAL_RECAP'\n    ]::text[];\n  elsif tg_table_name = 'matches' then\n    target_match := new.match_id;\n    target_tournament := new.tournament_id;\n    reason_value := 'CANONICAL_MATCH_CHANGED';\n    revision_value := pg_catalog.jsonb_build_object(\n      'matchId', target_match,\n      'matchRevision', new.match_revision,\n      'status', new.status,\n      'resultWinner', new.result_winner,\n      'scorecardComplete', new.scorecard_complete\n    );\n    engine_values := array[\n      'TEAM_MOMENTUM', 'TOURNAMENT_STORYLINES',\n      'TOURNAMENT_INTELLIGENCE', 'PROJECTION_EDITORIAL',\n      'TOURNAMENT_FINAL_RECAP'\n    ]::text[];\n  elsif tg_table_name = 'odds_published_snapshots' then\n    target_tournament := new.tournament_id;\n    reason_value := 'OFFICIAL_ODDS_PUBLICATION_CHANGED';\n    revision_value := pg_catalog.jsonb_build_object(\n      'publicationRevision', new.publication_revision,\n      'payloadHash', new.payload_hash,\n      'isCurrentOfficial', new.is_current_official\n    );\n    engine_values := array[\n      'TOURNAMENT_INTELLIGENCE', 'PROJECTION_EDITORIAL',\n      'TOURNAMENT_FINAL_RECAP'\n    ]::text[];\n  else\n    if new.is_current is not true then\n      return new;\n    end if;\n    target_tournament := new.tournament_id;\n    reason_value := 'NET_SKINS_CURRENT_RESULT_CHANGED';\n    revision_value := pg_catalog.jsonb_build_object(\n      'roundNumber', new.round_number,\n      'resultRevision', new.result_revision,\n      'payloadHash', new.payload_hash,\n      'isCurrent', new.is_current\n    );\n    engine_values := array['TOURNAMENT_STORYLINES']::text[];\n  end if;\n  if target_tournament is null then\n    raise exception using errcode = '55000',\n      message = 'PRODUCTION_ANNUAL_DERIVED_TRIGGER_TOURNAMENT_REQUIRED';\n  end if;\n\n  perform pg_catalog.pg_advisory_xact_lock_shared(\n    production_control.scoring_admission_lock_key()\n  );\n  select value.tournament_id into strict current_tournament\n  from production_control.current_tournament_pointer_v1 value\n  where value.scope_key = production_control.canonical_execution_resource_id_v1();\n  -- Setup and historical corrections for a non-current tournament do not\n  -- create current-runtime work. Their own activation preparation owns their\n  -- future generation and readiness markers.\n  if target_tournament <> current_tournament then\n    return case when tg_op = 'DELETE' then old else new end;\n  end if;\n  if target_tournament = '2026' then\n    if not exists (\n      select 1 from scoring_authority.ingress_gates value\n      where value.tournament_id = '2026' and value.state = 'OPEN'\n        and value.authority = 'SUPABASE'\n    ) then\n      raise exception using errcode = '55000',\n        message = 'PRODUCTION_ANNUAL_DERIVED_ADMISSION_CLOSED';\n    end if;\n  else\n    select value.runtime_generation_id into runtime_generation\n    from production_control.annual_scoring_runtime_authorities_v1 value\n    where value.tournament_id = target_tournament\n      and value.authority_status = 'ACTIVE'\n      and value.admission_state = 'OPEN';\n    if runtime_generation is null then\n      raise exception using errcode = '55000',\n        message = 'PRODUCTION_ANNUAL_DERIVED_RUNTIME_REQUIRED';\n    end if;\n  end if;\n\n  if tg_table_name = 'hole_scores' or (tg_table_name = 'matches' and exists (\n    select 1 from scoring_authority.score_derived_intents_v1 intent\n    where intent.tournament_id = target_tournament and intent.match_id = target_match\n      and intent.source_transaction = txid_current() and intent.family = 'COMPETITION')) then\n    perform production_control.append_score_derived_intent_v1(\n      target_tournament, target_match,\n      (select round_number from scoring_authority.matches where match_id = target_match),\n      'COMPETITION', reason_value, revision_value || jsonb_strip_nulls(jsonb_build_object(\n        'mutationKey', case when tg_table_name = 'hole_scores' then (case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end)->'mutation_key' else null end)), runtime_generation\n    );\n    return case when tg_op = 'DELETE' then old else new end;\n  end if;\n  foreach engine_value in array engine_values loop\n    insert into scoring_authority.competition_recalculation_jobs (\n      tournament_id, round_number, engine_key, status,\n      requested_source_revision, requested_at, started_at, completed_at,\n      last_error_code, last_error_safe, runtime_generation_id,\n      claim_token, claimed_by, lease_expires_at, updated_at\n    ) values (\n      target_tournament, 0, engine_value, 'PENDING',\n      pg_catalog.jsonb_build_object(\n        'reason', reason_value, 'revision', revision_value,\n        'transactional', true\n      ), pg_catalog.clock_timestamp(), null, null, null, null,\n      runtime_generation, null, null, null, pg_catalog.clock_timestamp()\n    ) on conflict (tournament_id, round_number, engine_key) do update set\n      status = 'PENDING',\n      requested_source_revision = excluded.requested_source_revision,\n      requested_at = excluded.requested_at,\n      started_at = null, completed_at = null,\n      last_error_code = null, last_error_safe = null,\n      runtime_generation_id = excluded.runtime_generation_id,\n      claim_token = null, claimed_by = null, lease_expires_at = null,\n      updated_at = excluded.updated_at;\n  end loop;\n  return case when tg_op = 'DELETE' then old else new end;\nend;\n",
        "new": "\ndeclare\n  target_match text;\n  target_tournament text;\n  current_tournament text;\n  runtime_generation uuid;\n  reason_value text;\n  revision_value jsonb;\n  prior_revision_value jsonb;\n  engine_values text[];\n  engine_value text;\nbegin\n  if tg_table_schema <> 'scoring_authority'\n     or tg_table_name not in (\n       'hole_scores', 'matches', 'odds_published_snapshots',\n       'net_skins_v1_result_revisions'\n     ) then\n    raise exception using errcode = '55000',\n      message = 'PRODUCTION_ANNUAL_DERIVED_TRIGGER_SCOPE_INVALID';\n  end if;\n  if tg_table_name = 'hole_scores' then\n    target_match := case when tg_op = 'DELETE'\n      then old.match_id else new.match_id end;\n    select value.tournament_id into target_tournament\n    from scoring_authority.matches value\n    where value.match_id = target_match;\n    reason_value := 'CANONICAL_HOLE_SCORE_CHANGED';\n    revision_value := pg_catalog.jsonb_build_object(\n      'matchId', target_match,\n      'holeNumber', case when tg_op = 'DELETE'\n        then old.hole_number else new.hole_number end,\n      'holeRevision', case when tg_op = 'DELETE'\n        then old.hole_revision else new.hole_revision end\n    );\n    engine_values := array[\n      'TEAM_MOMENTUM', 'TOURNAMENT_STORYLINES',\n      'TOURNAMENT_INTELLIGENCE', 'PROJECTION_EDITORIAL',\n      'TOURNAMENT_FINAL_RECAP'\n    ]::text[];\n  elsif tg_table_name = 'matches' then\n    target_match := new.match_id;\n    target_tournament := new.tournament_id;\n    reason_value := 'CANONICAL_MATCH_CHANGED';\n    revision_value := pg_catalog.jsonb_build_object(\n      'matchId', target_match,\n      'matchRevision', new.match_revision,\n      'status', new.status,\n      'resultWinner', new.result_winner,\n      'scorecardComplete', new.scorecard_complete\n    );\n    if tg_op='UPDATE' then\n      prior_revision_value:=jsonb_build_object('matchId',old.match_id,'matchRevision',old.match_revision,\n        'status',old.status,'resultWinner',old.result_winner,'scorecardComplete',old.scorecard_complete);\n    else\n      -- A canonical INSERT proves absence of this match in the prior source.\n      prior_revision_value:=jsonb_build_object('matchId',target_match,'sourceAbsent',true);\n    end if;\n    engine_values := array[\n      'TEAM_MOMENTUM', 'TOURNAMENT_STORYLINES',\n      'TOURNAMENT_INTELLIGENCE', 'PROJECTION_EDITORIAL',\n      'TOURNAMENT_FINAL_RECAP'\n    ]::text[];\n  elsif tg_table_name = 'odds_published_snapshots' then\n    target_tournament := new.tournament_id;\n    reason_value := 'OFFICIAL_ODDS_PUBLICATION_CHANGED';\n    revision_value := pg_catalog.jsonb_build_object(\n      'publicationRevision', new.publication_revision,\n      'payloadHash', new.payload_hash,\n      'isCurrentOfficial', new.is_current_official\n    );\n    engine_values := array[\n      'TOURNAMENT_INTELLIGENCE', 'PROJECTION_EDITORIAL',\n      'TOURNAMENT_FINAL_RECAP'\n    ]::text[];\n  else\n    if new.is_current is not true then\n      return new;\n    end if;\n    target_tournament := new.tournament_id;\n    reason_value := 'NET_SKINS_CURRENT_RESULT_CHANGED';\n    revision_value := pg_catalog.jsonb_build_object(\n      'roundNumber', new.round_number,\n      'resultRevision', new.result_revision,\n      'payloadHash', new.payload_hash,\n      'isCurrent', new.is_current\n    );\n    engine_values := array['TOURNAMENT_STORYLINES']::text[];\n  end if;\n  if target_tournament is null then\n    raise exception using errcode = '55000',\n      message = 'PRODUCTION_ANNUAL_DERIVED_TRIGGER_TOURNAMENT_REQUIRED';\n  end if;\n\n  perform pg_catalog.pg_advisory_xact_lock_shared(\n    production_control.scoring_admission_lock_key()\n  );\n  select value.tournament_id into strict current_tournament\n  from production_control.current_tournament_pointer_v1 value\n  where value.scope_key = production_control.canonical_execution_resource_id_v1();\n  -- Setup and historical corrections for a non-current tournament do not\n  -- create current-runtime work. Their own activation preparation owns their\n  -- future generation and readiness markers.\n  if target_tournament <> current_tournament then\n    return case when tg_op = 'DELETE' then old else new end;\n  end if;\n  if target_tournament = '2026' then\n    if not exists (\n      select 1 from scoring_authority.ingress_gates value\n      where value.tournament_id = '2026' and value.state = 'OPEN'\n        and value.authority = 'SUPABASE'\n    ) then\n      raise exception using errcode = '55000',\n        message = 'PRODUCTION_ANNUAL_DERIVED_ADMISSION_CLOSED';\n    end if;\n  else\n    select value.runtime_generation_id into runtime_generation\n    from production_control.annual_scoring_runtime_authorities_v1 value\n    where value.tournament_id = target_tournament\n      and value.authority_status = 'ACTIVE'\n      and value.admission_state = 'OPEN';\n    if runtime_generation is null then\n      raise exception using errcode = '55000',\n        message = 'PRODUCTION_ANNUAL_DERIVED_RUNTIME_REQUIRED';\n    end if;\n  end if;\n\n  if tg_table_name = 'hole_scores' or (tg_table_name = 'matches' and exists (\n    select 1 from scoring_authority.score_derived_intents_v1 intent\n    where intent.tournament_id = target_tournament and intent.match_id = target_match\n      and intent.source_transaction = txid_current() and intent.family = 'COMPETITION')) then\n    perform production_control.append_score_derived_intent_v1(\n      target_tournament, target_match,\n      (select round_number from scoring_authority.matches where match_id = target_match),\n      'COMPETITION', reason_value, revision_value || jsonb_strip_nulls(jsonb_build_object(\n        'mutationKey', case when tg_table_name = 'hole_scores' then (case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end)->'mutation_key' else null end)), runtime_generation\n    );\n    return case when tg_op = 'DELETE' then old else new end;\n  end if;\n  foreach engine_value in array engine_values loop\n    insert into scoring_authority.competition_recalculation_jobs (\n      tournament_id, round_number, engine_key, status,\n      requested_source_revision, requested_at, started_at, completed_at,\n      last_error_code, last_error_safe, runtime_generation_id,\n      claim_token, claimed_by, lease_expires_at, updated_at\n    ) values (\n      target_tournament, 0, engine_value, 'PENDING',\n      pg_catalog.jsonb_build_object(\n        'reason', reason_value, 'revision', revision_value,\n        'priorRevision', prior_revision_value, 'transactional', true\n      ), pg_catalog.clock_timestamp(), null, null, null, null,\n      runtime_generation, null, null, null, pg_catalog.clock_timestamp()\n    ) on conflict (tournament_id, round_number, engine_key) do update set\n      status = 'PENDING',\n      requested_source_revision = excluded.requested_source_revision,\n      requested_at = excluded.requested_at,\n      started_at = null, completed_at = null,\n      last_error_code = null, last_error_safe = null,\n      runtime_generation_id = excluded.runtime_generation_id,\n      claim_token = null, claimed_by = null, lease_expires_at = null,\n      updated_at = excluded.updated_at;\n  end loop;\n  return case when tg_op = 'DELETE' then old else new end;\nend;\n"
      }
    ]
  }
]$manifest$;
begin
 select jsonb_build_object(
  'v1',(select to_jsonb(t)from production_control.worker_supervisor_installation_v1 t where singleton),
  'v2',(select to_jsonb(t)from production_control.worker_supervisor_queue_installation_v2 t where singleton),
  'v3',(select to_jsonb(t)from production_control.worker_supervisor_publisher_installation_v3 t where singleton),
  'v4',(select to_jsonb(t)from production_control.worker_supervisor_safeupdate_installation_v4 t where singleton),
  'v5',(select to_jsonb(t)from production_control.worker_supervisor_global_fault_installation_v5 t where singleton),
  'v6',(select to_jsonb(t)from production_control.worker_supervisor_retry_envelope_installation_v6 t where singleton),
  'v7',(select to_jsonb(t)from production_control.worker_supervisor_routing_closure_installation_v7 t where singleton))into history_snapshot;
 for patch in select value from jsonb_array_elements(manifest)loop
  select p.prosrc,jsonb_build_object('owner',p.proowner,'acl',p.proacl,'security',p.prosecdef,'config',p.proconfig,
   'language',p.prolang,'volatile',p.provolatile,'parallel',p.proparallel,'strict',p.proisstrict)
   into strict body,before_metadata from pg_proc p where p.oid=(patch->>'signature')::regprocedure;
  hash:=encode(extensions.digest(body,'sha256'),'hex');
  if hash not in(patch->>'old_hash',patch->>'new_hash')then raise exception 'SUPERVISOR_FUNCTION_PREDECESSOR_DRIFT: %',patch->>'signature';end if;
  if hash=patch->>'old_hash'then
   definition:=pg_get_functiondef((patch->>'signature')::regprocedure);
   for edit in select value from jsonb_array_elements(patch->'edits')loop
    if(length(body)-length(replace(body,edit->>'old','')))/length(edit->>'old')<>1 then raise exception 'SUPERVISOR_PATCH_COUNT_DRIFT';end if;
    body:=replace(body,edit->>'old',edit->>'new');definition:=replace(definition,edit->>'old',edit->>'new');
   end loop;
   if encode(extensions.digest(body,'sha256'),'hex')<>patch->>'new_hash'then raise exception 'SUPERVISOR_PATCH_HASH_DRIFT';end if;
   execute definition;
  end if;
  select jsonb_build_object('owner',p.proowner,'acl',p.proacl,'security',p.prosecdef,'config',p.proconfig,
   'language',p.prolang,'volatile',p.provolatile,'parallel',p.proparallel,'strict',p.proisstrict)
   into strict after_metadata from pg_proc p where p.oid=(patch->>'signature')::regprocedure;
  if before_metadata is distinct from after_metadata then raise exception 'SUPERVISOR_FUNCTION_METADATA_DRIFT';end if;
  all_metadata:=all_metadata||jsonb_build_object(patch->>'signature',after_metadata);
 end loop;

 if exists(select 1 from production_control.derived_attempt_cycle_installation_v1 where singleton and
  (installed_hash is distinct from manifest->0->>'new_hash' or metadata is distinct from all_metadata
   or history is distinct from history_snapshot))then raise exception 'DERIVED_ATTEMPT_RECEIPT_DRIFT';end if;
 insert into production_control.derived_attempt_cycle_installation_v1(singleton,predecessor_hash,installed_hash,metadata,history)
 values(true,manifest->0->>'old_hash',manifest->0->>'new_hash',all_metadata,history_snapshot)on conflict do nothing;
end;$correction$;
commit;
